1import { useState, useEffect, useMemo } from "react";
2import Header from "./components/Header";
3import EntryCard from "./components/EntryCard";
4import Drawer from "./components/Drawer";
5
6const ENTRIES_PER_PAGE = 5;
7
8function App() {
9  const [entries, setEntries] = useState([]);
10  const [isLoading, setIsLoading] = useState(true);
11  const [error, setError] = useState(null);
12  const [refreshKey, setRefreshKey] = useState(0);
13  const [selectedEntry, setSelectedEntry] = useState(null);
14  const [query, setQuery] = useState("");
15  const [currentPage, setCurrentPage] = useState(1);
16
17  const filteredEntries = useMemo(function () {
18    if (!query.trim()) return entries;
19    const lower = query.toLowerCase();
20    return entries.filter(function (entry) {
21      return (
22        entry.title.toLowerCase().includes(lower) ||
23        entry.content.toLowerCase().includes(lower)
24      );
25    });
26  }, [entries, query]);
27
28  const pagedEntries = useMemo(function () {
29    const start = (currentPage - 1) * ENTRIES_PER_PAGE;
30    return filteredEntries.slice(start, start + ENTRIES_PER_PAGE);
31  }, [filteredEntries, currentPage]);
32
33  useEffect(function () {
34    async function loadEntries() {
35      setIsLoading(true);
36      setError(null);
37      try {
38        const res = await fetch("https://api.programiz.pro/api/Demo/v1/journal-entries");
39        if (!res.ok) {
40          throw new Error("Could not load entries. Status: " + res.status);
41        }
42        const data = await res.json();
43        const mapped = data.map((post) => {
44          return {
45            ...post,
46            date: new Date(post.date).toLocaleDateString("en-US", {
47              year: "numeric", month: "short", day: "numeric"
48            }).toUpperCase()
49          };
50        });
51        setEntries(mapped);
52        setIsLoading(false);
53      } catch (err) {
54        setError(err.message);
55        setIsLoading(false);
56      }
57    }
58    loadEntries();
59  }, [refreshKey]);
60
61  function handleRefresh() {
62    setRefreshKey((k) => k + 1);
63  }
64
65  function handleSelectEntry(entry) {
66    setSelectedEntry(entry);
67  }
68
69  function handleQueryChange(newQuery) {
70    setQuery(newQuery);
71    setCurrentPage(1);
72  }
73
74  function handleNext() {
75    setCurrentPage(function (p) {
76      return Math.min(p + 1, Math.ceil(filteredEntries.length / ENTRIES_PER_PAGE));
77    });
78  }
79
80  function handlePrev() {
81    setCurrentPage(function (p) { return Math.max(p - 1, 1); });
82  }
83
84  return (
85    <div className="main-container">
86      <Header query={query} onQueryChange={handleQueryChange} />
87      <section className="entries-section">
88        <div className="entry-list-header">
89          <h3>Recent Entries</h3>
90          <span className="entry-count">{filteredEntries.length}</span>
91          <button className="btn btn-secondary" onClick={handleRefresh}>Refresh</button>
92        </div>
93        {isLoading ? (
94          <p className="loading-state">Loading entries...</p>
95        ) : error ? (
96          <div className="error-banner">
97            <p className="error-label">Something went wrong.</p>
98            <p className="error-detail">{error}</p>
99          </div>
100        ) : pagedEntries.length === 0 ? (
101          <p className="empty-state">No entries found.</p>
102        ) : (
103          pagedEntries.map((entry) => (
104            <EntryCard
105              key={entry.id}
106              id={entry.id}
107              title={entry.title}
108              date={entry.date}
109              content={entry.content}
110              author={entry.author}
111              onSelect={handleSelectEntry}
112            />
113          ))
114        )}
115        {!isLoading && !error && filteredEntries.length > ENTRIES_PER_PAGE && (
116          <div className="pagination">
117            <button
118              className="btn btn-secondary"
119              onClick={handlePrev}
120              disabled={currentPage === 1}
121            >
122              Previous
123            </button>
124            <button
125              className="btn btn-secondary"
126              onClick={handleNext}
127              disabled={currentPage === Math.ceil(filteredEntries.length / ENTRIES_PER_PAGE)}
128            >
129              Next
130            </button>
131          </div>
132        )}
133      </section>
134      <Drawer
135        entry={selectedEntry}
136        onClose={() => setSelectedEntry(null)}
137      />
138    </div>
139  );
140}
141
142export default App;

1import { useRef, useEffect } from "react";
2
3function Header({ query, onQueryChange }) {
4  const searchRef = useRef(null);
5
6  useEffect(function () {
7    searchRef.current.focus();
8  }, []);
9
10  function handleChange(e) {
11    onQueryChange(e.target.value);
12  }
13
14  function handleClear() {
15    onQueryChange("");
16    searchRef.current.focus();
17  }
18
19  return (
20    <header className="header">
21      <h2 className="title-primary">My Daily Journal</h2>
22      <p className="subtitle">Capture your thoughts, one day at a time.</p>
23      <div className="header-search">
24        <input
25          ref={searchRef}
26          className="search-input"
27          type="text"
28          placeholder="Search entries..."
29          value={query}
30          onChange={handleChange}
31        />
32        {query && (
33          <button className="btn-clear" onClick={handleClear}>Clear</button>
34        )}
35      </div>
36    </header>
37  );
38}
39
40export default Header;

